 'cancel-pending-protocol':()=>{state.pendingSetup=null;render();},
 'member-tab':el=>{if(!['overview','history','programs','profile'].includes(el.dataset.tab))return;state.tab=el.dataset.tab;render();window.scrollTo(0,0);$(`[data-action="member-tab"][data-tab="${state.tab}"]`)?.focus({preventScroll:true});},
 'assess':()=>openSessionPicker('strength','assessment'),'train':()=>openSessionPicker('strength','training'),'continue-program':el=>beginProgram(el.dataset.programId),'start-rom':()=>beginSetup('assessment','rom'),

 'setup-type':el=>changeSetupMode(el.dataset.type),'setup-positions':el=>{state.setup.positions=Number(el.dataset.value);if(state.setup.programLoad){const plan=memberPrograms().find(p=>p.id===state.setup.programId);if(plan){const resolved=resolveProgramTargets(plan,state.personId,state.setup.positions);state.setup.targets=resolved.targets;state.setup.programSource=resolved.source;}}if(!currentAngles().includes(state.setup.angle))state.setup.angle=0;resetSetupAcceptance();renderSetupControl('#setup-count-'+el.dataset.value);},
 'reps-minus':()=>{state.setup.reps=Math.max(1,state.setup.reps-1);resetSetupAcceptance();renderSetupControl(state.setup.reps===1?'#reps-plus':'#reps-minus');},'reps-plus':()=>{state.setup.reps=Math.min(5,state.setup.reps+1);resetSetupAcceptance();renderSetupControl(state.setup.reps===5?'#reps-minus':'#reps-plus');},
 'leave-setup':()=>{state.stage=null;state.nav='people';state.tab='overview';render();},'start-session':startSession,'begin-rep':beginRep,
 'complete-rep':()=>completeRep(),'manual-rep':()=>completeRep(state.setup.type==='rom'?'Manual limit recorded':state.setup.type==='endurance'?'Effort released':'Manual stop'),
 'pause-session':()=>{state.session.paused=!state.session.paused;render();updateLive();},
 'end-session':()=>{state.session.paused=true;render();openModal('end-session');},'save-partial':()=>finishSession(true),
 'discard-session':()=>{stopTimer();state.stage=null;state.session=null;state.overlay=null;state.guided=state.actor==='member';state.nav='people';state.tab='overview';render();},
 'fast-forward':fastForward,
 'toggle-guided':()=>{if(state.guided){if(state.session)state.session.paused=true;render();openModal('clinician',{takeover:true});}else{state.guided=true;render();updateLive();}},
 'help':()=>{if(state.session)state.session.paused=true;render();openModal('help');},
 'station':()=>openModal('station'),'settings':()=>{if(state.actor==='coach')openModal('settings');},
 'switch-clinician':()=>openModal('clinician'),'staff-entry':()=>openModal('clinician'),
 'confirm-clinician':clinicianConfirmed,'close-modal':closeModal,
 'phone-entry':()=>openModal('phone'),'code-entry':()=>openModal('member-code'),'member-approved':memberApproved,
 'confirm-member-code':()=>{if($('#member-code').value==='2468')memberApproved();else $('#auth-error').textContent='Use the demo code 2468 to continue.';},
 'member-welcome':()=>{state.welcomeMode='member';render();},'lock-station':()=>{state.nav='welcome';state.welcomeMode=null;state.personId=null;state.stage=null;state.overlay=null;render();},
 'signout':()=>{state.nav='welcome';state.welcomeMode='member';state.personId=null;state.result=null;state.session=null;state.stage=null;render();},
